const { Pool } = require('pg');

// pg reads PGHOST / PGPORT / PGDATABASE / PGUSER / PGPASSWORD from the
// environment automatically, so the pool needs no explicit options.
const pool = new Pool();

module.exports = {
  /**
   * Run a parameterised query against the shared pool.
   * @param {string} text - SQL with $1-style placeholders
   * @param {Array} [params]
   * @returns {Promise<import('pg').QueryResult>}
   */
  query: (text, params) => pool.query(text, params),
  pool,
};

