const BASE_URL = '/api';

/**
 * Wrapper around fetch that speaks JSON and throws a friendly Error
 * (with .code and .status) when the backend returns a business error.
 */
async function requestJson(path, options = {}) {
  const response = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) {
    const error = new Error(body.message || `Request failed (${response.status})`);
    error.code = body.error;
    error.status = response.status;
    throw error;
  }
  return body;
}

// --- UC-003: Payroll calculation ------------------------------------------

/** Trigger payroll calculation for a validated pay period. */
export function calculatePayroll(payPeriodId) {
  return requestJson('/payroll/calculate', {
    method: 'POST',
    body: JSON.stringify({ payPeriodId }),
  });
}

/** Fetch the calculated payroll (lines + derived totals) for a period. */
export function getPayroll(payPeriodId) {
  return requestJson(`/payroll/${payPeriodId}`);
}

