// UC-003 - Payroll calculation screen.
// Accounting staff selects a validated pay period, clicks "Calculate Payroll",
// and reviews the totals, variance warning, and per-staff breakdown.
import React, { useState } from 'react';
import { calculatePayroll, getPayroll } from '../api/client';
import PayrollLineTable from '../components/PayrollLineTable';

export default function PayrollCalcPage() {
  // Pay-period pickers land with UC-001/002's screens; a plain ID field keeps
  // this page usable stand-alone until then.
  const [payPeriodId, setPayPeriodId] = useState('');
  const [summary, setSummary] = useState(null);
  const [payroll, setPayroll] = useState(null);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);

  async function refreshPayroll(id) {
    setPayroll(await getPayroll(id));
  }

  async function handleCalculate() {
    setBusy(true);
    setError(null);
    setSummary(null);
    try {
      const result = await calculatePayroll(payPeriodId.trim());
      setSummary(result);
      await refreshPayroll(payPeriodId.trim());
    } catch (err) {
      // 409 = period not validated yet; 404 = wrong ID - show as-is
      setError(err.message);
    } finally {
      setBusy(false);
    }
  }

  async function handleLoadExisting() {
    setBusy(true);
    setError(null);
    try {
      await refreshPayroll(payPeriodId.trim());
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="page payroll-calc-page">
      <h1>Payroll Calculation (UC-003)</h1>

      <div className="controls">
        <label htmlFor="payPeriodId">Pay period ID</label>
        <input
          id="payPeriodId"
          value={payPeriodId}
          onChange={(e) => setPayPeriodId(e.target.value)}
          placeholder="Validated pay period UUID"
        />
        <button onClick={handleCalculate} disabled={busy || !payPeriodId.trim()}>
          {busy ? 'Working...' : 'Calculate Payroll'}
        </button>
        <button onClick={handleLoadExisting} disabled={busy || !payPeriodId.trim()}>
          Load Existing
        </button>
      </div>

      {error && <p className="error">{error}</p>}

      {summary && (
        <div className="summary-card">
          <h2>Calculation Summary</h2>
          <p>Status: <strong>{summary.status}</strong></p>
          <p>Total gross: <strong>${summary.totalGross.toFixed(2)}</strong></p>
          <p>Total net: <strong>${summary.totalNet.toFixed(2)}</strong></p>
          <p>
            Lines: {summary.lineCount}
            {summary.incompleteCount > 0 && (
              <span className="warning">
                {' '}({summary.incompleteCount} incomplete - excluded from totals until resolved)
              </span>
            )}
          </p>
          {summary.varianceWarning && (
            <p className="warning">
              Warning: period total differs from the previous cycle by{' '}
              {(summary.varianceWarning.vsPrevious * 100).toFixed(0)}% (threshold{' '}
              {(summary.varianceWarning.threshold * 100).toFixed(0)}%). Double-check before
              submitting for approval.
            </p>
          )}
        </div>
      )}

      {payroll && (
        <div className="payroll-detail">
          <h2>Per-Staff Breakdown</h2>
          <PayrollLineTable lines={payroll.lines} />
        </div>
      )}
    </div>
  );
}

// UC-003 - Per-staff payroll breakdown table.
// Pure display component: receives dollar figures from the API, renders them.
import React from 'react';

function money(value) {
  return `$${Number(value).toFixed(2)}`;
}

export default function PayrollLineTable({ lines }) {
  if (!lines || lines.length === 0) {
    return <p>No payroll lines yet. Run &quot;Calculate Payroll&quot; first.</p>;
  }

  return (
    <table className="payroll-line-table">
      <thead>
        <tr>
          <th>Staff</th>
          <th>Gross</th>
          <th>Incentive</th>
          <th>CPF (Employee)</th>
          <th>CPF (Employer)</th>
          <th>SDL</th>
          <th>Other Deductions</th>
          <th>Net Pay</th>
          <th>Status</th>
        </tr>
      </thead>
      <tbody>
        {lines.map((line) => (
          <tr key={line.id} className={line.lineStatus === 'incomplete' ? 'line-incomplete' : ''}>
            <td>{line.fullName}</td>
            <td>{money(line.grossPay)}</td>
            <td>{money(line.incentiveAmount)}</td>
            <td>{money(line.cpfEmployee)}</td>
            <td>{money(line.cpfEmployer)}</td>
            <td>{money(line.sdl)}</td>
            <td>{money(line.otherDeductions)}</td>
            <td>{money(line.netPay)}</td>
            <td>
              {line.lineStatus === 'incomplete' ? (
                // Incomplete lines are excluded from the period total until resolved
                <span className="badge badge-incomplete" title={line.notes || ''}>
                  Incomplete{line.notes ? ` - ${line.notes}` : ''}
                </span>
              ) : (
                <span className="badge badge-complete">Complete</span>
              )}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

