import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// Dev server for the payroll-automation frontend.
// Calls to /api are proxied to the Express backend (backend/src/server.js,
// port 3001) so the browser can use same-origin paths like /api/payroll/...
// (see src/api/client.js, which prefixes every request with /api).
export default defineConfig({
  server: {
    port: 5173,
    proxy: {
      '/api': 'http://localhost:3001',
    },
  },
  plugins: [react()],
});

// React entry point. Mounts <App /> into the #root div declared in index.html.
import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import './styles/main.css';

createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

// Root component. Only UC-003 (payroll calculation) is built so far; the other
// use-case pages get added to a nav/router here as they land.
import React from 'react';
import PayrollCalcPage from './pages/PayrollCalcPage';

export default function App() {
  return (
    <div className="app">
      <header className="app-header">
        <span className="app-title">Payroll Automation</span>
      </header>
      <main className="app-main">
        <PayrollCalcPage />
      </main>
    </div>
  );
}

/* Baseline styling for the payroll-automation frontend. Class names match the
   markup in App.jsx, pages/PayrollCalcPage.jsx and components/PayrollLineTable.jsx. */

:root {
  --bg: #f4f6f8;
  --surface: #ffffff;
  --border: #d9dee3;
  --text: #1f2933;
  --muted: #6b7280;
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --warning-bg: #fff7ed;
  --warning-text: #b45309;
  --error-bg: #fef2f2;
  --error-text: #b91c1c;
  --ok-bg: #ecfdf5;
  --ok-text: #047857;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.app-header {
  background: #0f172a;
  color: #fff;
  padding: 0.85rem 1.5rem;
}

.app-title {
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.app-main {
  max-width: 1000px;
  margin: 0 auto;
  padding: 1.5rem;
}

.page h1 {
  font-size: 1.4rem;
  margin: 0 0 1rem;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.6rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  margin-bottom: 1.25rem;
}

.controls label {
  font-weight: 600;
  font-size: 0.9rem;
}

.controls input {
  flex: 1 1 260px;
  min-width: 220px;
  padding: 0.5rem 0.65rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 0.9rem;
}

button {
  padding: 0.5rem 0.95rem;
  border: none;
  border-radius: 6px;
  background: var(--primary);
  color: #fff;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
}

