import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// Dev server for the payroll-automation frontend.
// Calls to /api are proxied to the Express backend (backend/src/server.js,
// port 3001) so the browser can use same-origin paths like /api/payroll/...
// (see src/api/client.js, which prefixes every request with /api).
export default defineConfig({
  server: {
    port: 5173,
    proxy: {
      '/api': 'http://localhost:3001',
    },
  },
  plugins: [react()],
});

// React entry point. Mounts <App /> into the #root div declared in index.html.
import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import './styles/main.css';

createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

// Root component. Only UC-003 (payroll calculation) is built so far; the other
// use-case pages get added to a nav/router here as they land.
import React from 'react';
import PayrollCalcPage from './pages/PayrollCalcPage';

export default function App() {
  return (
    <div className="app">
      <header className="app-header">
        <span className="app-title">Payroll Automation</span>
      </header>
      <main className="app-main">
        <PayrollCalcPage />
      </main>
    </div>
  );
}

