Write-Output "=== PostgreSQL install dirs ==="; if (Test-Path 'C:\Program Files\PostgreSQL') { Get-ChildItem 'C:\Program Files\PostgreSQL' | Select-Object Name } else { Write-Output "none in C:\Program Files\PostgreSQL" }
Write-Output "`n=== Postgres Windows service ==="; $svc = Get-Service | Where-Object { $_.Name -like '*postgres*' -or $_.DisplayName -like '*postgres*' }; if ($svc) { $svc | Select-Object Name, Status, DisplayName } else { Write-Output "no postgres service found" }
Write-Output "`n=== winget ==="; try { winget --version } catch { Write-Output "winget NOT found" }
Write-Output "`n=== choco ==="; try { choco --version } catch { Write-Output "choco NOT found" }
Write-Output "`n=== scoop ==="; if (Get-Command scoop -ErrorAction SilentlyContinue) { scoop --version } else { Write-Output "scoop NOT found" }

$svc = Get-Service 'postgresql-x64-18'; Write-Output "Service status: $($svc.Status)"
if ($svc.Status -ne 'Running') { Write-Output "Attempting to start service..."; try { Start-Service 'postgresql-x64-18' -ErrorAction Stop; Write-Output "Started." } catch { Write-Output "Could not start (may need admin): $($_.Exception.Message)" } }
$psql = 'C:\Program Files\PostgreSQL\18\bin\psql.exe'
Write-Output "`npsql present: $(Test-Path $psql)"
if (Test-Path $psql) { & $psql --version }
Write-Output "`n=== listening ports (looking for 5432) ==="; (Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | Where-Object { $_.LocalPort -eq 5432 } | Select-Object -First 1 LocalAddress, LocalPort)

$data = 'C:\Program Files\PostgreSQL\18\data'
Write-Output "Data dir present: $(Test-Path $data)"
if (Test-Path "$data\postgresql.conf") {
  $portLine = Select-String -Path "$data\postgresql.conf" -Pattern '^\s*port\s*=' | Select-Object -First 1
  if ($portLine) { Write-Output "port setting: $($portLine.Line.Trim())" } else { Write-Output "port not explicitly set -> default 5432" }
}
if (Test-Path "$data\pg_hba.conf") {
  Write-Output "`n=== pg_hba.conf (active auth rules) ==="
  Get-Content "$data\pg_hba.conf" | Where-Object { $_ -match '^\s*(local|host)\s' -and $_ -notmatch '^\s*#' }
}

